add_action( 'wp_footer', 'perfectpixel_image_magnifier' );

function perfectpixel_image_magnifier() {
	$zoom = max( 1.2, min( 6, (float) '{{magnifier_zoom}}' ) );
	$size = max( 60, min( 400, (int) '{{magnifier_size}}' ) );
	?>
	<script>
	( function ( zoom, size ) {
		if ( ! window.matchMedia( '(hover: hover) and (pointer: fine)' ).matches ) {
			return;
		}
		var lens = document.createElement( 'div' );
		lens.setAttribute( 'aria-hidden', 'true' );
		lens.style.cssText = 'position:absolute;z-index:99999;pointer-events:none;display:none;border-radius:50%;border:3px solid #fff;box-shadow:0 2px 10px rgba(0,0,0,.35);background-repeat:no-repeat;width:' + size + 'px;height:' + size + 'px';
		document.body.appendChild( lens );
		var move = function ( e ) {
			var img = e.currentTarget, rect = img.getBoundingClientRect();
			var x = e.clientX - rect.left, y = e.clientY - rect.top;
			if ( x < 0 || y < 0 || x > rect.width || y > rect.height ) {
				lens.style.display = 'none';
				return;
			}
			lens.style.display = 'block';
			lens.style.backgroundImage = 'url("' + ( img.currentSrc || img.src ) + '")';
			lens.style.backgroundSize = ( rect.width * zoom ) + 'px ' + ( rect.height * zoom ) + 'px';
			lens.style.backgroundPosition = ( size / 2 - x * zoom ) + 'px ' + ( size / 2 - y * zoom ) + 'px';
			lens.style.left = ( e.pageX - size / 2 ) + 'px';
			lens.style.top = ( e.pageY - size / 2 ) + 'px';
		};
		document.querySelectorAll( 'img.perfectpixel-zoom, .perfectpixel-zoom img' ).forEach( function ( img ) {
			img.style.cursor = 'zoom-in';
			img.addEventListener( 'mousemove', move );
			img.addEventListener( 'mouseleave', function () {
				lens.style.display = 'none';
			} );
		} );
	} )( <?php echo (float) $zoom; ?>, <?php echo (int) $size; ?> );
	</script>
	<?php
}
